#!/usr/bin/env python3
"""Wrap deploy/monitoring/alerts.yml (plain Prometheus rules) into a PrometheusRule resource.

Run after editing alerts.yml; CI fails if the generated file is stale.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "deploy/monitoring/alerts.yml"
TARGET = ROOT / "deploy/monitoring/prometheusrule.yaml"

HEADER = """\
# GENERATED by scripts/render_prometheusrule.py from alerts.yml. Do not edit by hand.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: media-converter
  labels:
    release: kube-prometheus-stack
spec:
"""


def render() -> str:
    body = [line for line in SOURCE.read_text().splitlines() if not line.startswith("#")]
    return HEADER + "\n".join(f"  {line}" if line else "" for line in body) + "\n"


if __name__ == "__main__":
    import sys

    rendered = render()
    if "--check" in sys.argv:
        sys.exit(0 if TARGET.exists() and TARGET.read_text() == rendered else "prometheusrule.yaml is stale")
    TARGET.write_text(rendered)
    print(f"wrote {TARGET.relative_to(ROOT)}")
